@startuml

enum LevelOfTutoring {
  PrimarySchool
  HighSchool
  University
}

enum PaymentKind {
  CreditCard
  WireTransfer
}

abstract class TutoringRole {
  + name : string
  + email : string
}

class Student extends TutoringRole {}

class Tutor extends TutoringRole {
  + bankAccount : string
}

class Subject {
  + name : string
}

class TutoringOffer {
  + hourlyPrice : float
}

class TutorAvailability {
  + dayOfWeek : string
  + startTime : time
  + endTime : time
}

class TutoringRequest {
  + suggestedDate : date
  + suggestedTime : time
  + level : LevelOfTutoring
}

class TutoringSession {
  + sessionDate : date
  + sessionTime : time
}

class Payment {
  + amount : float
  + paymentKind : PaymentKind
}

class BestTutorAward {
  + month : int
}

Student "1" -- "*" TutoringRequest : makes
Tutor "1" -- "*" TutoringRequest : receives
Subject "1" -- "*" TutoringOffer : in
Tutor "1" -- "*" TutoringOffer : offers
Tutor "1" -- "*" TutorAvailability : specifies
TutoringRequest "1" -- "0..1" TutoringSession : results in
Student "1" -- "*" TutoringSession : attends
Tutor "1" -- "*" TutoringSession : conducts
TutoringSession "1" -- "0..1" TutoringSession : followUp
TutoringSession "1" -- "0..1" Payment : paidBy
Tutor "1" -- "*" BestTutorAward : receives
Subject "1" -- "*" BestTutorAward : for

@enduml

